    L = [0] + sorted([a % n for a in A if a % n != 0])
    R = [n - a for a in L[1:]] + [0]
    for i in range(len(L) - 1):
        L[i + 1] += L[i]
        R[len(L) - i - 2] += R[len(L) - i - 1]

    res = 10 ** 20
    for l, r in zip(L, R):
        res = min(res, max(l, r))
    return res


