def get_count(s, leader, r):
    count = 0

    pre_upper_pos = 0

    for li in leader:
        lower_pos = bisect.bisect_left(s, li - r)
        upper_pos = bisect.bisect_right(s, li)
        if pre_upper_pos < lower_pos:
            count += lower_pos - pre_upper_pos
        pre_upper_pos = upper_pos
    count += len(s) - pre_upper_pos

    return count

