from itertools import accumulate

def solve():
    file_input = stdin

    N = int(file_input.readline())
    img = tuple(tuple(map(int, line.split())) for line in file_input)

    acc_row = (tuple(accumulate(line)) + (0,) for line in img)

    acc_col = (tuple(accumulate(line)) + (0,) for line in zip(*img))
    acc_col_1 = next(acc_col)
    acc_col = tuple(zip(*acc_col))

    ans = 0
    for i, tpl_1 in enumerate(zip(img, acc_row)):
        img_i, acc_row_i = tpl_1
        for j, img_j in enumerate(img[i:], start=i):
            if acc_row_i[j] - acc_row_i[i - 1] > ans:
                ans = acc_row_i[j] - acc_row_i[i - 1]

            if i == j:
                continue

            col_max = acc_col_1[j] - acc_col_1[i - 1]

            for acc_col_j_k, acc_col_i_k, img_i_k, img_j_k in zip(acc_col[j], acc_col[i - 1], img_i[1:], img_j[1:]):
                col = acc_col_j_k - acc_col_i_k

                if col_max > 0:
                    c_ans = col_max + col
                    if c_ans > ans:
                        ans = c_ans
                else:
                    if col > ans:
                        ans = col

                t_col_max = col_max + img_i_k + img_j_k
                if t_col_max > col:
                    col_max = t_col_max
                else:
                    col_max = col
    print(ans)

