from collections import defaultdict
import sys
def solve():
    readline = sys.stdin.readline
    write = sys.stdout.write
    MOD = 10**9 + 7
    Na, Nt, Ng, Nc = map(int, readline().split())
    L = Na + Nt + Ng + Nc
    M = int(readline())
    MP = {}
    S = []
    for i in range(M):
        s = readline().strip()
        s1, s2 = s.split(": ")
        MP[s1] = s2.split(" ")
        S.append(s1)
    R = []
    memo = {}
    def dfs(s):
        if s in memo:
            return memo[s]
        r = []
        for e in MP[s]:
            if e[0] == "[":
                w = 0
                for v in map("ATGC".index, e[1:-1]):
                    w |= 1 << v
                r.append(w)
            else:
                r0 = dfs(e)
                if r0 is None:
                    return None
                r.extend(r0)
        if len(r) > L:
            return None
        memo[s] = r
        return r
    res = dfs(S[0])
    if res is None or len(res) < L:
        write("0\n")
        return
    L = len(res)

    T = [defaultdict(int) for i in range(L+1)]
    T[0][Na, Nt, Ng, Nc] = 1
    for k in range(L):
        s = res[k]
        p0 = s & 1; p1 = s & 2; p2 = s & 4; p3 = s & 8
        T1 = T[k+1]
        for (a, b, c, d), v in T[k].items():
            v %= MOD
            if p0 and a:
                T1[a-1, b, c, d] += v
            if p1 and b:
                T1[a, b-1, c, d] += v
            if p2 and c:
                T1[a, b, c-1, d] += v
            if p3 and d:
                T1[a, b, c, d-1] += v
    write("%d\n" % (T[L][0, 0, 0, 0] % MOD))
solve()

from enum import IntEnum


class Action(IntEnum):
    ADD = 1
    SEARCH = 2
    REMOVE = 3


class Color(IntEnum):
    BLACK = 0
    RED = 1

    @staticmethod
    def flip(c):
        return [Color.RED, Color.BLACK][c.value]


class Node:
    __slots__ = ('value', 'left', 'right', 'color', 'valid')

    def __init__(self, value):
        self.value = value
        self.left = Leaf
        self.right = Leaf
        self.color = Color.RED
        self.valid = True

    def flip_color(self):
        self.color = Color.flip(self.color)

    def is_red(self):
        return self.color == Color.RED

    def __str__(self):
        return ('(' + str(self.left) + ', '
                + str(self.value) + ', ' + str(self.right) + ')')


class LeafNode(Node):
    def __init__(self):
        self.value = None
        self.left = None
        self.right = None
        self.color = None
        self.valid = False

    def flip_color(self):
        pass

    def is_red(self):
        return False

    def __str__(self):
        return 'Leaf'


Leaf = LeafNode()


class RedBlackBST:
    def __init__(self):
        self.root = Leaf

    def add(self, value):
        def _add(node):
            if node is Leaf:
                node = Node(value)
            if node.value > value:
                node.left = _add(node.left)
            elif node.value < value:
                node.right = _add(node.right)
            else:
                if not node.valid:
                    node.valid = True

            node = self._balance(node)
            return node

        self.root = _add(self.root)
        self.root.color = Color.BLACK

    def _balance(self, node):
        if node.right.is_red() and not node.left.is_red():
            node = self._rotate_left(node)
        if node.left.is_red() and node.left.left.is_red():
            node = self._rotate_right(node)
        if node.left.is_red() and node.right.is_red():
            node = self._flip_colors(node)
        return node

    def _rotate_left(self, node):
        x = node.right
        node.right = x.left
        x.left = node
        x.color = node.color
        node.color = Color.RED
        return x

    def _rotate_right(self, node):
        x = node.left
        node.left = x.right
        x.right = node
        x.color = node.color
        node.color = Color.RED
        return x

    def _flip_colors(self, node):
        node.flip_color()
        node.left.flip_color()
        node.right.flip_color()
        return node

    def remove(self, value):
        def _remove(node):
            if node is Leaf:
                return
            if node.value > value:
                _remove(node.left)
            elif node.value < value:
                _remove(node.right)
            else:
                node.valid = False

        _remove(self.root)

    def count(self, min_, max_):
        def _range(node):
            if node is Leaf:
                return 0

            if node.value > max_:
                return _range(node.left)
            elif node.value < min_:
                return _range(node.right)
            else:
                count = _range(node.left) + _range(node.right)
                if node.valid:
                    count += 1
                return count

        return _range(self.root)

    def __str__(self):
        return str(self.root)


def count_intersections(segments):
    segments.sort()
    tree = RedBlackBST()
    count = 0
    for seg in segments:
        x, action, y = seg
        if action == Action.SEARCH:
            count += tree.count(*y)
        elif action == Action.ADD:
            tree.add(y)
        elif action == Action.REMOVE:
            tree.remove(y)

    return count


