class Rollinhash:
    def __init__(self, S):
        N = len(S)
        self.mod = 10**9+9
        self.base = 2009          
        self.has = [0]*(N+1)
        self.power = [1]*(N+1)
        for i in range(N):
            s = S[i]
            self.has[i+1] = (self.has[i]*self.base + s)%self.mod
            self.power[i+1] = self.power[i]*self.base%self.mod

    def rh(self, i, j):
        return (self.has[j] - self.has[i]*self.power[j-i])%self.mod

